package com.example.demo3;

import java.io.*;
import java.util.Arrays;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.List;

import jakarta.servlet.RequestDispatcher;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.*;
import jakarta.servlet.annotation.*;

@WebServlet("/productList")
public class HelloServlet extends HttpServlet {




    public void doGet(HttpServletRequest request, HttpServletResponse response) throws IOException, ServletException {
       // model
        List<Map<String, Object>> products = Arrays.asList(
                product("product 1", 10.0),
                product("product 2", 20.0),
                product("product 3", 30.0),
                product("product 4", 40.0)
        );
        request.setAttribute("products", products);
        // view
        RequestDispatcher rd=request.getRequestDispatcher("productList.jsp");
        rd.forward(request, response);


    }

    private Map<String, Object> product(String name, double price) {
        Map<String, Object> product = new LinkedHashMap<>();
        product.put("name", name);
        product.put("price", price);
        return product;
    }


}

package com.example.demo3.dao;

import com.example.demo3.model.Review;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;

public class ReviewDAO {
	private static final AtomicInteger NEXT_ID = new AtomicInteger(1);
	private static final Map<Integer, List<Review>> REVIEWS_BY_PRODUCT = new ConcurrentHashMap<>();

	public List<Review> findByProductId(int productId) {
		List<Review> reviews = REVIEWS_BY_PRODUCT.get(productId);
		if (reviews == null) {
			return new ArrayList<>();
		}
		return new ArrayList<>(reviews);
	}

	public Review save(int productId, String username, String comment, int rating) {
		Review review = new Review(NEXT_ID.getAndIncrement(), productId, username, comment, rating);
		REVIEWS_BY_PRODUCT.computeIfAbsent(productId, key -> new ArrayList<>()).add(review);
		return review;
	}
}

package com.example.demo3.dao;

import com.example.demo3.config.DatabaseConfig;
import com.example.demo3.model.Review;

import java.sql.*;
import java.util.ArrayList;
import java.util.List;

public class ReviewDAO {

	public List<Review> findByProductId(int productId) throws SQLException {
		List<Review> reviews = new ArrayList<>();
		String sql = "SELECT id, product_id, username, comment, rating FROM reviews WHERE product_id = ? ORDER BY created_at DESC";

		try (Connection conn = DatabaseConfig.getConnection();
		     PreparedStatement stmt = conn.prepareStatement(sql)) {
			stmt.setInt(1, productId);
			try (ResultSet rs = stmt.executeQuery()) {
				while (rs.next()) {
					Review review = new Review(
							rs.getInt("id"),
							rs.getInt("product_id"),
							rs.getString("username"),
							rs.getString("comment"),
							rs.getInt("rating")
					);
					reviews.add(review);
				}
			}
		}
		return reviews;
	}

	public Review save(int productId, String username, String comment, int rating) throws SQLException {
		String sql = "INSERT INTO reviews (product_id, username, comment, rating) VALUES (?, ?, ?, ?)";

		try (Connection conn = DatabaseConfig.getConnection();
		     PreparedStatement stmt = conn.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
			stmt.setInt(1, productId);
			stmt.setString(2, username);
			stmt.setString(3, comment);
			stmt.setInt(4, Math.max(1, Math.min(5, rating))); // Clamp rating between 1-5

			stmt.executeUpdate();

			try (ResultSet generatedKeys = stmt.getGeneratedKeys()) {
				if (generatedKeys.next()) {
					int id = generatedKeys.getInt(1);
					return new Review(id, productId, username, comment, rating);
				}
			}
		}
		throw new SQLException("Failed to create review");
	}

	public double getAverageRating(int productId) throws SQLException {
		String sql = "SELECT AVG(rating) as avg_rating FROM reviews WHERE product_id = ?";

		try (Connection conn = DatabaseConfig.getConnection();
		     PreparedStatement stmt = conn.prepareStatement(sql)) {
			stmt.setInt(1, productId);
			try (ResultSet rs = stmt.executeQuery()) {
				if (rs.next()) {
					double avg = rs.getDouble("avg_rating");
					return Double.isNaN(avg) ? 0.0 : avg;
				}
			}
		}
		return 0.0;
	}

	public int getReviewCount(int productId) throws SQLException {
		String sql = "SELECT COUNT(*) as count FROM reviews WHERE product_id = ?";

		try (Connection conn = DatabaseConfig.getConnection();
		     PreparedStatement stmt = conn.prepareStatement(sql)) {
			stmt.setInt(1, productId);
			try (ResultSet rs = stmt.executeQuery()) {
				if (rs.next()) {
					return rs.getInt("count");
				}
			}
		}
		return 0;
	}
}

package com.example.demo3.model.controller;

import com.example.demo3.model.dao.UserDAO;
import com.example.demo3.model.service.RateLimiter;
import com.example.demo3.model.util.AppConstants;
import jakarta.servlet.annotation.WebServlet;
import jakarta.servlet.http.HttpServlet;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;

import java.io.IOException;

@WebServlet("/account/delete")
public class DeleteAccountServlet extends HttpServlet {
	private final UserDAO userDAO = new UserDAO();
	private static final RateLimiter RATE_LIMITER = new RateLimiter();
	private static final int MAX_REQUESTS = 5;
	private static final long WINDOW_MILLIS = 10_000L;

	@Override
	protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws IOException {
		String ip = req.getRemoteAddr();
		String key = "account:delete:" + (ip == null ? "unknown" : ip);
		if (!RATE_LIMITER.allow(key, MAX_REQUESTS, WINDOW_MILLIS)) {
			resp.sendError(429, "Too many requests. Please wait a few seconds and try again.");
			return;
		}
		Object userObj = req.getSession(false) == null ? null : req.getSession(false).getAttribute(AppConstants.SESSION_LOGGED_IN_USER);
		// that check the user login
		if (userObj == null) {
			resp.sendRedirect(req.getContextPath() + "/login.jsp?message="
					+ java.net.URLEncoder.encode("Please login first", java.nio.charset.StandardCharsets.UTF_8));
			return;
		}
		String username = String.valueOf(userObj);

		try {
			boolean deleted = userDAO.deleteByUsername(username);
			// invalidate session either way
			if (req.getSession(false) != null) {
				req.getSession(false).invalidate();
			}

			if (deleted) {
				resp.sendRedirect(req.getContextPath() + "/register.jsp?message="
						+ java.net.URLEncoder.encode("Account deleted", java.nio.charset.StandardCharsets.UTF_8));
			} else {
				resp.sendRedirect(req.getContextPath() + "/products?error="
						+ java.net.URLEncoder.encode("Account not found", java.nio.charset.StandardCharsets.UTF_8));
			}
		} catch (Exception e) {
			resp.sendRedirect(req.getContextPath() + "/products?error="
					+ java.net.URLEncoder.encode("Failed to delete account", java.nio.charset.StandardCharsets.UTF_8));
		}
	}
}

package com.example.demo3.model.controller;

import com.example.demo3.model.dao.UserDAO;
import com.example.demo3.model.service.RedisCacheService;
import com.example.demo3.model.service.RateLimiter;
import com.example.demo3.model.util.AppConstants;
import com.example.demo3.model.util.JwtUtil;
import jakarta.servlet.annotation.WebServlet;
import jakarta.servlet.http.Cookie;
import jakarta.servlet.http.HttpServlet;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;

import java.io.IOException;
import java.time.Duration;
import java.util.Optional;

@WebServlet("/account/delete")
public class DeleteAccountServlet extends HttpServlet {
	private final UserDAO userDAO = new UserDAO();
	private final RedisCacheService redisCacheService = new RedisCacheService();
	private static final RateLimiter RATE_LIMITER = new RateLimiter();
	private static final int MAX_REQUESTS = 5;
	private static final long WINDOW_MILLIS = 10_000L;

	@Override
	protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws IOException {
		String ip = req.getRemoteAddr();
		String key = "account:delete:" + (ip == null ? "unknown" : ip);
		if (!RATE_LIMITER.allow(key, MAX_REQUESTS, WINDOW_MILLIS)) {
			resp.sendError(429, "Too many requests. Please wait a few seconds and try again.");
			return;
		}
		Object userObj = req.getSession(false) == null ? null : req.getSession(false).getAttribute(AppConstants.SESSION_LOGGED_IN_USER);
		// that check the user login
		if (userObj == null) {
			resp.sendRedirect(req.getContextPath() + "/login.jsp?message="
					+ java.net.URLEncoder.encode("Please login first", java.nio.charset.StandardCharsets.UTF_8));
			return;
		}
		String username = String.valueOf(userObj);

		try {
			boolean deleted = userDAO.deleteByUsername(username);
			// invalidate session either way
			if (req.getSession(false) != null) {
				req.getSession(false).invalidate();
			}

			// Revoke JWT in Redis (if any) and clear cookie
			String token = null;
			Cookie[] cookies = req.getCookies();
			if (cookies != null) {
				for (Cookie c : cookies) {
					if (AppConstants.JWT_COOKIE_NAME.equals(c.getName())) {
						token = c.getValue();
						break;
					}
				}
			}
			if (token != null && !token.trim().isEmpty()) {
				Optional<Long> exp = JwtUtil.extractExpiresAtMillis(token);
				if (exp.isPresent()) {
					long ttlMillis = exp.get() - System.currentTimeMillis();
					if (ttlMillis > 0) {
						redisCacheService.revokeJwt(token, Duration.ofMillis(ttlMillis));
					}
				}
				Cookie jwtCookie = new Cookie(AppConstants.JWT_COOKIE_NAME, "");
				jwtCookie.setHttpOnly(true);
				jwtCookie.setPath(req.getContextPath().isEmpty() ? "/" : req.getContextPath());
				jwtCookie.setMaxAge(0);
				resp.addCookie(jwtCookie);
			}

			if (deleted) {
				resp.sendRedirect(req.getContextPath() + "/register.jsp?message="
						+ java.net.URLEncoder.encode("Account deleted", java.nio.charset.StandardCharsets.UTF_8));
			} else {
				resp.sendRedirect(req.getContextPath() + "/products?error="
						+ java.net.URLEncoder.encode("Account not found", java.nio.charset.StandardCharsets.UTF_8));
			}
		} catch (Exception e) {
			resp.sendRedirect(req.getContextPath() + "/products?error="
					+ java.net.URLEncoder.encode("Failed to delete account", java.nio.charset.StandardCharsets.UTF_8));
		}
	}
}

package com.example.demo3.model.controller;

import jakarta.servlet.annotation.WebServlet;
import jakarta.servlet.http.HttpServlet;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import jakarta.servlet.http.HttpSession;

import com.example.demo3.model.service.RateLimiter;

import java.io.IOException;

@WebServlet("/logout")
public class LogoutServlet extends HttpServlet {
  private static final RateLimiter RATE_LIMITER = new RateLimiter();
  private static final int MAX_REQUESTS = 5;
  private static final long WINDOW_MILLIS = 10_000L;

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        doPost(req, resp);
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws IOException {
		String ip = req.getRemoteAddr();
		String key = "logout:" + (ip == null ? "unknown" : ip);
		if (!RATE_LIMITER.allow(key, MAX_REQUESTS, WINDOW_MILLIS)) {
			resp.sendError(429, "Too many requests. Please wait a few seconds and try again.");
			return;
		}
        HttpSession session = req.getSession(false);
        if (session != null) {
            session.invalidate();
        }


        resp.sendRedirect(req.getContextPath() + "/login.jsp?message="
                + java.net.URLEncoder.encode("Logged out successfully", java.nio.charset.StandardCharsets.UTF_8));
    }
}

package com.example.demo3.model.controller;

import jakarta.servlet.annotation.WebServlet;
import jakarta.servlet.http.HttpServlet;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import jakarta.servlet.http.HttpSession;
import jakarta.servlet.http.Cookie;

import com.example.demo3.model.service.RateLimiter;
import com.example.demo3.model.service.RedisCacheService;
import com.example.demo3.model.util.AppConstants;
import com.example.demo3.model.util.JwtUtil;

import java.io.IOException;
import java.time.Duration;
import java.util.Optional;

@WebServlet("/logout")
public class LogoutServlet extends HttpServlet {
  private static final RateLimiter RATE_LIMITER = new RateLimiter();
	private final RedisCacheService redisCacheService = new RedisCacheService();
  private static final int MAX_REQUESTS = 5;
  private static final long WINDOW_MILLIS = 10_000L;

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp) throws IOException {
        doPost(req, resp);
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws IOException {
		String ip = req.getRemoteAddr();
		String key = "logout:" + (ip == null ? "unknown" : ip);
		if (!RATE_LIMITER.allow(key, MAX_REQUESTS, WINDOW_MILLIS)) {
			resp.sendError(429, "Too many requests. Please wait a few seconds and try again.");
			return;
		}
        HttpSession session = req.getSession(false);
        if (session != null) {
            session.invalidate();
        }

    // Revoke JWT in Redis until it expires, then clear cookie
    String token = null;
    Cookie[] cookies = req.getCookies();
    if (cookies != null) {
      for (Cookie c : cookies) {
        if (AppConstants.JWT_COOKIE_NAME.equals(c.getName())) {
          token = c.getValue();
          break;
        }
      }
    }
    if (token != null && !token.trim().isEmpty()) {
      Optional<Long> exp = JwtUtil.extractExpiresAtMillis(token);
      if (exp.isPresent()) {
        long ttlMillis = exp.get() - System.currentTimeMillis();
        if (ttlMillis > 0) {
          redisCacheService.revokeJwt(token, Duration.ofMillis(ttlMillis));
        }
      }

      Cookie jwtCookie = new Cookie(AppConstants.JWT_COOKIE_NAME, "");
      jwtCookie.setHttpOnly(true);
      jwtCookie.setPath(req.getContextPath().isEmpty() ? "/" : req.getContextPath());
      jwtCookie.setMaxAge(0);
      resp.addCookie(jwtCookie);
    }


        resp.sendRedirect(req.getContextPath() + "/login.jsp?message="
                + java.net.URLEncoder.encode("Logged out successfully", java.nio.charset.StandardCharsets.UTF_8));
    }
}
